package gov.takx.core.view.gui.mapobjectmanager;

import gov.nasa.worldwind.render.Size;
import gov.nasa.worldwind.util.tree.BasicTreeLayout;
import gov.nasa.worldwind.util.tree.ScrollFrame;
import gov.nasa.worldwind.util.tree.Tree;

import java.awt.Dimension;

/**
 * Custom implementation of WorldWind's {@link BasicTreeLayout}.
 * <p/>
 * This custom implementation allows callers to specify the maximum height of the {@link ScrollFrame}
 * generated by this class.
 *
 */
public class DataMonitorTreeLayout extends BasicTreeLayout
{
    /**
     * Constructor.
     *
     * @param tree The tree that this layout will be responsible for rendering.
     * @param x    X coordinate of the upper left corner of the tree frame.
     * @param y    Y coordinate of the upper left corner of the tree frame, measured from the top of the screen.
     */
    public DataMonitorTreeLayout(Tree tree, int x, int y)
    {
        super(tree, x, y);
    }

    /**
     * Returns a {@link DataMonitorScrollFrame} rather than
     * a standard {@link ScrollFrame}.
     *
     * @return A {@link DataMonitorScrollFrame}
     * @see DataMonitorScrollFrame
     */
    @Override
    protected ScrollFrame createFrame()
    {
        DataMonitorScrollFrame dmsf = new DataMonitorScrollFrame();

        // Size the frame to fit the contents
        dmsf.setSize(new Size(Size.NATIVE_DIMENSION, 0, null, Size.NATIVE_DIMENSION, 0, null));
        dmsf.setEnableResizeControl(false);
        dmsf.setContents(this);

        return dmsf;
    }

    // TODO overridden to fix a bug that causes the tree layout to invalidate when computing the size with null frame
    // TODO bounds. This override can be removed when the bug is fixed.
    @Override
    protected boolean mustRecomputeSize(Dimension frameSize)
    {
        return this.mustRecomputeSize
                || (this.previousSizeBounds == null && frameSize != null)
                || (frameSize != null && this.previousSizeBounds.width != frameSize.width);
    }
}
